using System;using System.Linq;using System.Reflection;using NUnit.Framework;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.Quests;using Rootborn.Game.StudentLife;using Rootborn.UI.StudentLife;using Rootborn.UI.Quests;using UnityEditor;using UnityEngine;using UnityEngine.UI;using Object=UnityEngine.Object;
namespace Rootborn.Tests.EditMode.UI.StudentLife{public sealed class ExplorationAndStoryTextPresentationTests{GameObject canvas,point;string language;GameDataRegistry registry;[SetUp]public void Setup(){language=GameText.Language;registry=AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");GameDataRegistryProvider.SetOverrideForTests(registry);canvas=new GameObject("StoryTextCanvas",typeof(RectTransform),typeof(Canvas));point=new GameObject("PromptFixture",typeof(LocationActivityInteractor));}[TearDown]public void Cleanup(){Object.DestroyImmediate(canvas);Object.DestroyImmediate(point);GameText.Language=language;GameDataRegistryProvider.ClearOverrideForTests();}
[TestCase("ko","[E] 공방 살펴보기")][TestCase("en","[E] Explore Workshop")]public void RealWorldLocationPromptUsesCurrentLanguage(string lang,string expected){GameText.Language=lang;var location=registry.LocationIdentities.Single(x=>x!=null&&x.Location.Id=="location.workshop");point.GetComponent<LocationActivityInteractor>().Bind(location);Assert.That(point.GetComponent<LocationActivityInteractor>().InteractionPrompt,Is.EqualTo(expected));}
[TestCase("ko","[E] 이곳 살펴보기")][TestCase("en","[E] Explore this place")]public void EmptyLocationHasFriendlyLocalizedPrompt(string lang,string expected){GameText.Language=lang;Assert.That(point.GetComponent<LocationActivityInteractor>().InteractionPrompt,Is.EqualTo(expected));}
[TestCase("ko")][TestCase("en")]public void CampaignObjectiveRowsResolveRegisteredObjectiveNamesAndVisitProtocol(string lang){GameText.Language=lang;var p=StudentDayResultPanel.EnsureInScene(canvas.GetComponent<Canvas>());p.Show(null,new StudentDaySummary(1,Array.Empty<string>(),Array.Empty<string>(),string.Empty,string.Empty,string.Empty,string.Empty));foreach(var name in new[]{"SelfStudy","Archive","Ledger","StoreWork","WorkshopWork","Teacher"})Assert.That(p.ResolveText("opening.campaign.objective."+name),Is.EqualTo(GameText.Get(AssetDatabase.LoadAssetAtPath<CampaignActivityLogObjective>("Assets/Data/StudentLife/MainStory/Campaigns/Objective_"+name+".asset").DisplayNameKey)),"Read-only UI resolution must include nested registered campaign objectives");var visit=p.ResolveText("location:location.library:visited");Assert.That(visit,Is.EqualTo(GameText.Format("day-result.location-visited",GameText.Get("location.library.name"))));Assert.That(visit,Does.Not.Contain(":").And.Not.Contain("location.library"));}
[TestCase("ko",QuestChainState.Available)][TestCase("ko",QuestChainState.Active)][TestCase("ko",QuestChainState.Tracked)][TestCase("ko",QuestChainState.Paused)][TestCase("ko",QuestChainState.Blocked)][TestCase("ko",QuestChainState.Completed)][TestCase("ko",QuestChainState.Failed)][TestCase("ko",QuestChainState.Expired)][TestCase("en",QuestChainState.Available)][TestCase("en",QuestChainState.Active)][TestCase("en",QuestChainState.Tracked)][TestCase("en",QuestChainState.Paused)][TestCase("en",QuestChainState.Blocked)][TestCase("en",QuestChainState.Completed)][TestCase("en",QuestChainState.Failed)][TestCase("en",QuestChainState.Expired)]public void StorySummaryUsesAuthoredTitleLocalizedStateAndObjectiveCountWithoutMutatingDefinition(string lang,QuestChainState state){GameText.Language=lang;var chain=AssetDatabase.LoadAssetAtPath<QuestChainDefinition>("Assets/Data/StudentLife/MainStory/QuestChain_SchoolOpening.asset");var objective=chain.Steps.First().Objectives.First();string before=EditorJsonUtility.ToJson(chain);string text=Format(chain,state,objective,0);Assert.That(text,Does.Contain(GameText.Get(chain.DisplayNameKey)).And.Contain(GameText.Get("quest.chain.state."+state.ToString().ToLowerInvariant())).And.Contain(GameText.Get(objective.DisplayKey)).And.Contain("0 / "+objective.RequiredCount));Assert.That(text,Does.Not.Contain(chain.Id).And.Not.Contain("quest.chain.").And.Not.Contain("opening.chain.name"));Assert.That(EditorJsonUtility.ToJson(chain),Is.EqualTo(before));}
[Test]public void MissingStoryTitleFallsBackWithoutRevealingInternalId(){var chain=ScriptableObject.CreateInstance<QuestChainDefinition>();try{chain.ConfigureForTests("fixture.chain.secret","fixture.chain.secret",string.Empty,string.Empty,Array.Empty<ScriptableObject>(),Array.Empty<QuestConditionBase>(),Array.Empty<QuestConditionBase>(),Array.Empty<QuestConditionBase>(),Array.Empty<QuestRewardBase>(),0);GameText.Language="ko";var text=Format(chain,QuestChainState.Tracked,null,0);Assert.That(text,Does.Contain(GameText.Get("quest.chain.generic")).And.Not.Contain(chain.Id));}finally{Object.DestroyImmediate(chain);}}
[TestCase("ko","잠긴 기록실 문")][TestCase("en","The locked archive door")]public void ArchiveRouteAndObjectiveUseFullyLocalizedAuthoredTitle(string lang,string expected){GameText.Language=lang;foreach(var path in new[]{"Assets/Data/StudentLife/MainStory/Campaigns/Route_Archive.asset","Assets/Data/StudentLife/MainStory/Campaigns/Objective_Archive.asset"}){var asset=AssetDatabase.LoadAssetAtPath<ScriptableObject>(path);var key=(string)asset.GetType().GetProperty("DisplayNameKey").GetValue(asset);Assert.That(GameText.Get(key),Is.EqualTo(expected));}}
static string Format(QuestChainDefinition chain,QuestChainState state,QuestObjectiveBase objective,int progress){var type=typeof(QuestChainRuntimeInstaller).Assembly.GetType("Rootborn.UI.Quests.QuestChainSummaryPresentation");Assert.That(type,Is.Not.Null,"Day result must format authored story title/state rather than dumping its internal chain ID");return (string)type.GetMethod("Build",BindingFlags.Static|BindingFlags.Public).Invoke(null,new object[]{chain,state,objective,progress});}
}}
